<style>
  :root{
    --red:#d81b1b;
    --blue:#164a9c;
    --yellow:#f2c300;
    --black:#111111;
    --paper:#f2efe6;
    --ink-soft:#3b3a36;
    --rule:1px solid var(--black);
    --thick:10px solid var(--black);
    --pad:clamp(20px,5vw,72px);
    --mono:"IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
    --sans:"Jost", "Futura", "Century Gothic", ui-sans-serif, system-ui, sans-serif;
  }
  *{box-sizing:border-box}
  html{background:var(--paper); scroll-behavior:smooth}
  body{
    margin:0; background:var(--paper); color:var(--black);
    font-family:var(--sans); font-weight:400; font-size:17px; line-height:1.55;
    -webkit-font-smoothing:antialiased;
  }
  ::selection{background:var(--yellow); color:var(--black)}
  a{color:inherit}
  a:focus-visible,button:focus-visible{outline:3px solid var(--blue); outline-offset:4px}
  h1,h2,h3,p{margin:0}
  .wrap{max-width:1240px; margin:0 auto; padding-inline:var(--pad)}

  /* ---------- top bar ---------- */
  .topbar{
    display:flex; justify-content:space-between; align-items:center; gap:16px;
    padding-block:14px; border-bottom:var(--thick);
    font-family:var(--mono); font-size:11px; letter-spacing:.16em; text-transform:uppercase;
  }
  .topbar .dot{display:inline-block; width:10px; height:10px; margin-right:10px; vertical-align:-1px; background:var(--red)}
  .topbar .right{display:flex; align-items:center; gap:10px}
  .topbar .right i{display:block; width:10px; height:10px}
  .topbar .right i:nth-child(1){background:var(--blue)}
  .topbar .right i:nth-child(2){background:var(--yellow)}
  .topbar .right i:nth-child(3){background:var(--black)}

  /* ---------- hero ---------- */
  .hero{padding-block:clamp(28px,5vw,64px) clamp(40px,6vw,80px)}
  .hero-grid{display:grid; grid-template-columns:1.02fr .98fr; gap:clamp(28px,4vw,64px); align-items:end}
  .eyebrow{font-family:var(--mono); font-size:11px; letter-spacing:.18em; text-transform:uppercase; display:flex; flex-wrap:wrap; align-items:center; gap:10px}
  .eyebrow .bar{display:inline-block; width:34px; height:2px; background:var(--black)}
  h1{
    font-size:clamp(2.5rem,6.4vw,5.6rem); line-height:.94; font-weight:500;
    letter-spacing:-.025em; margin-top:22px; text-wrap:balance;
  }
  h1 .accent{color:var(--red)}
  .hero-sub{margin-top:clamp(20px,3vw,34px); max-width:34ch; font-size:clamp(1rem,1.5vw,1.17rem); color:var(--ink-soft)}
  .hero-sub strong{font-weight:500; color:var(--black)}
  .byline{
    margin-top:30px; padding-top:16px; border-top:var(--rule);
    display:flex; flex-wrap:wrap; gap:8px 26px; font-family:var(--mono);
    font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--ink-soft);
  }
  .byline b{font-weight:500; color:var(--black)}
  .cta-row{margin-top:32px; display:flex; flex-wrap:wrap; align-items:center; gap:18px 26px}
  .btn{
    display:inline-flex; align-items:center; gap:14px; text-decoration:none;
    background:var(--black); color:var(--paper); padding:15px 20px 15px 22px;
    font-family:var(--mono); font-size:11px; letter-spacing:.16em; text-transform:uppercase;
    border:2px solid var(--black); transition:background .18s ease,color .18s ease;
  }
  .btn span{transition:transform .18s ease}
